//! LWC decorator validation vs Babel class-features "Decorators are not enabled." and the
//! @lwc/compiler LWC1198 sniff, against shipped 9.5.3 (fixture generated by
//! notes/lwc-rust-migrate/proofs/decorators-not-enabled/dump-fixture.mjs; shipped messages have the
//! cwd prefix stripped, Rust keeps the filename as given).
//!
//! Shipped rule: babel-plugin-component skips (no validation, decorators left in place) a class with
//! no superclass, and leaves unknown-name decorators in place when nothing was LWC-transformed; Babel's
//! class-features then throws on any class still carrying decorators (private field / private method
//! messages first). @lwc/compiler maps that throw to LWC1198 iff the whole Babel message (filename +
//! code frame included) matches /\b(track|api|wire)\b/, else LWC1007. It is a real throw: in recovery
//! mode it replaces the collected LWC errors and has no location.
mod support;
use lwc_shared::CompileOptions;
use serde_json::Value;

const FIXTURE: &str = include_str!("fixtures/decorators-not-enabled-shipped.json");

#[test]
fn decorator_outcomes_match_shipped() {
    let cases: Vec<Value> = serde_json::from_str(FIXTURE).unwrap();
    assert!(cases.len() >= 50);
    let mut failures = vec![];
    for c in &cases {
        let id = c["id"].as_str().unwrap();
        let mut o = CompileOptions::default();
        o.name = "foo".into();
        o.namespace = "x".into();
        o.experimental_error_recovery_mode = c["recover"].as_bool().unwrap();
        o.api_version = c["opts"]["apiVersion"].as_u64().map(|v| v as u32);
        let r = lwc_compiler::dispatch(c["src"].as_str().unwrap(), c["filename"].as_str().unwrap(), &o).map_err(support::Thrown::from);
        let want = &c["shipped"];
        let got = match &r {
            Ok(_) => Value::from("ok"),
            Err(e) if e.name == Some("AggregateError") => {
                serde_json::json!({ "errors": e.errors.iter().map(|d| d.code).collect::<Vec<_>>() })
            }
            Err(e) => serde_json::json!({
                "code": e.code(),
                "message": e.message,
                "hasLocation": e.errors[0].location.is_some(),
            }),
        };
        let want = match want {
            Value::String(_) => want.clone(),
            w if !w["errors"].is_null() => serde_json::json!({ "errors": w["errors"] }),
            w => serde_json::json!({ "code": w["code"], "message": w["message"], "hasLocation": w["hasLocation"] }),
        };
        if got != want { failures.push(format!("{id}:\n  got  {got}\n  want {want}")); }
    }
    assert!(failures.is_empty(), "{} mismatches:\n{}", failures.len(), failures.join("\n"));
}
